#!/usr/bin/env python3
import os, sys, re, urllib.request, ssl
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field
from typing import List, Dict, Optional, Tuple, Any

XSD_NS = 'http://www.w3.org/2001/XMLSchema'
WSDL_NS = 'http://schemas.xmlsoap.org/wsdl/'

GO_KEYWORDS = {
    'break','default','func','interface','select','case','defer','go','map','struct','chan','else','goto','package','switch',
    'const','fallthrough','if','range','type','continue','for','import','return','var'
}


def local(tag):
    if tag is None: return ''
    return tag.split('}',1)[1] if tag.startswith('{') else tag

def nsuri(tag):
    if tag and tag.startswith('{'): return tag[1:].split('}',1)[0]
    return ''

def children(e, name=None):
    if e is None: return []
    return [c for c in list(e) if name is None or local(c.tag)==name]

def first(e, name):
    for c in list(e or []):
        if local(c.tag)==name: return c
    return None

def descendants(e, name):
    return [x for x in e.iter() if local(x.tag)==name]

def strip_prefix(q):
    if not q: return ''
    return q.split(':',1)[1] if ':' in q else q

def prefix(q):
    return q.split(':',1)[0] if q and ':' in q else ''

def go_name(s: str) -> str:
    if not s:
        return ''
    # The observed generator keeps underscores (e.g. GetWorkshops_V2) but removes other separators.
    out = []
    cap_next = True
    for ch in s:
        if ch == '_':
            out.append(ch); cap_next = True; continue
        if ch.isalnum():
            if cap_next:
                out.append(ch.upper())
            else:
                out.append(ch)
            cap_next = False
        else:
            cap_next = True
    res = ''.join(out)
    if not res:
        res = 'X'
    if res[0].isdigit():
        res = '_' + res
    if res in GO_KEYWORDS or res.lower() in GO_KEYWORDS:
        # Original appends underscore to identifiers colliding with Go keywords (return -> Return_).
        if res[0].isupper():
            res += '_'
    return res

def private_name(s: str) -> str:
    if not s: return s
    return s[0].lower() + s[1:]

def sanitize_const_suffix(v: str) -> str:
    if v == '':
        return 'Empty'
    parts = re.split(r'[^0-9A-Za-z_]+', v)
    return ''.join(go_name(p) for p in parts if p) or 'Value'

def doc_text(e) -> str:
    if e is None: return ''
    ann = first(e, 'annotation')
    if ann is not None:
        doc = first(ann, 'documentation')
        if doc is not None:
            return ' '.join(''.join(doc.itertext()).strip().split())
    return ''

@dataclass
class FieldDef:
    xml_name: str
    go_name: str
    go_type: str
    is_attr: bool=False
    ns: str=''
    doc: str=''
    anonymous: Optional['StructDef']=None
    embed: bool=False
    chardata: bool=False

@dataclass
class StructDef:
    name: str
    fields: List[FieldDef]=field(default_factory=list)
    xml_name: Optional[str]=None
    xml_ns: str=''
    alias: Optional[str]=None
    base: Optional[str]=None
    enum_values: List[Tuple[str,str]]=field(default_factory=list) # value, doc
    date_alias: bool=False
    emitted: bool=False

@dataclass
class MessagePart:
    name: str
    element: str=''
    type: str=''

@dataclass
class Operation:
    name: str
    input_msg: str=''
    output_msg: str=''
    doc: str=''
    action: str="''"
    req_type: str='EmptyString'
    resp_type: str='EmptyString'

@dataclass
class ServiceInterface:
    name: str
    operations: List[Operation]=field(default_factory=list)

class Generator:
    def __init__(self, wsdl_path, package, make_public=True, insecure=False):
        self.wsdl_path = wsdl_path
        self.package = package
        self.make_public = make_public
        self.insecure = insecure
        self.schemas = []
        self.schema_ns = ''
        self.structs: Dict[str,StructDef] = {}
        self.order: List[str] = []
        self.global_elements: Dict[str,ET.Element] = {}
        self.element_ns: Dict[str,str] = {}
        self.element_type_ref: Dict[str,str] = {}
        self.type_to_element: Dict[str,str] = {}
        self.type_to_element_ns: Dict[str,str] = {}
        self.global_attrs: Dict[str,ET.Element] = {}
        self.messages: Dict[str,List[MessagePart]] = {}
        self.port_types: Dict[str,List[Operation]] = {}
        self.bindings: Dict[str,Tuple[str,Dict[str,str]]] = {}
        self.interfaces: List[ServiceInterface] = []
        self.root = None
        self.wsdl_text = ''
        self.base_dir = ''
        self.loaded = set()

    def read_url_or_file(self, path):
        if re.match(r'https?://', path):
            print(f"🍀  Reading file {path}")
            ctx = None
            if self.insecure:
                ctx = ssl._create_unverified_context()
            with urllib.request.urlopen(path, context=ctx) as r:
                return r.read().decode('utf-8')
        ap = os.path.abspath(path)
        print(f"🍀  Reading file {ap}")
        try:
            with open(ap, 'r', encoding='utf-8') as f:
                return f.read()
        except FileNotFoundError:
            raise FileNotFoundError(f"open {ap}: no such file or directory")
        except Exception as e:
            raise Exception(f"open {ap}: {e}")

    def load(self):
        self.base_dir = os.path.dirname(os.path.abspath(self.wsdl_path)) or os.getcwd()
        self.wsdl_text = self.read_url_or_file(self.wsdl_path)
        try:
            self.root = ET.fromstring(self.wsdl_text)
        except ET.ParseError as e:
            raise Exception(str(e))
        for s in descendants(self.root, 'schema'):
            self.add_schema(s, self.base_dir)

    def add_schema(self, schema, base_dir):
        self.schemas.append(schema)
        tns = schema.attrib.get('targetNamespace','')
        if tns and not self.schema_ns:
            self.schema_ns = tns
        # imports/includes with schemaLocation (local/URL)
        for im in list(schema):
            if local(im.tag) in ('import','include'):
                loc = im.attrib.get('schemaLocation')
                if loc:
                    if re.match(r'https?://', loc):
                        key = loc; path = loc
                    else:
                        path = os.path.abspath(os.path.join(base_dir, loc))
                        key = path
                    if key in self.loaded: continue
                    self.loaded.add(key)
                    txt = self.read_url_or_file(path)
                    try:
                        r = ET.fromstring(txt)
                    except ET.ParseError as e:
                        raise Exception(str(e))
                    if local(r.tag) == 'schema':
                        self.add_schema(r, os.path.dirname(path) if not re.match(r'https?://', path) else base_dir)
                    else:
                        for ss in descendants(r, 'schema'):
                            self.add_schema(ss, os.path.dirname(path) if not re.match(r'https?://', path) else base_dir)

    def build(self):
        # Collect global declarations first
        for schema in self.schemas:
            tns = schema.attrib.get('targetNamespace','')
            for c in list(schema):
                if local(c.tag) == 'element' and c.attrib.get('name'):
                    name = c.attrib['name']
                    self.global_elements[name] = c
                    self.element_ns[name] = tns
                    typ = strip_prefix(c.attrib.get('type',''))
                    if typ:
                        self.element_type_ref[name] = typ
                        if typ not in self.type_to_element and not self.is_builtin(typ):
                            # Prefer references whose name differs from type; this approximates the original XMLName heuristic.
                            self.type_to_element[typ] = name
                            self.type_to_element_ns[typ] = tns
                elif local(c.tag) == 'complexType' and c.attrib.get('name'):
                    pass
                elif local(c.tag) == 'attribute' and c.attrib.get('name'):
                    self.global_attrs[c.attrib['name']] = c
        # More references from nested elements to assign XMLName for named types
        for schema in self.schemas:
            tns = schema.attrib.get('targetNamespace','')
            for e in descendants(schema, 'element'):
                name = e.attrib.get('name')
                typ = strip_prefix(e.attrib.get('type',''))
                if name and typ and not self.is_builtin(typ) and typ not in self.type_to_element and name != typ:
                    self.type_to_element[typ] = name
                    self.type_to_element_ns[typ] = tns
        self.emit_builtin_aliases()
        # Global simpleType declarations
        for schema in self.schemas:
            for c in list(schema):
                if local(c.tag) == 'simpleType' and c.attrib.get('name'):
                    self.parse_simple_type(c.attrib['name'], c)
        # Global elements before named types (observed for document wrapper elements)
        for schema in self.schemas:
            tns = schema.attrib.get('targetNamespace','')
            for c in list(schema):
                if local(c.tag) == 'element' and c.attrib.get('name'):
                    self.parse_global_element(c, tns)
        # Named complex types
        for schema in self.schemas:
            tns = schema.attrib.get('targetNamespace','')
            for c in list(schema):
                if local(c.tag) == 'complexType' and c.attrib.get('name'):
                    self.parse_complex_type(c.attrib['name'], c, tns, is_global_type=True)
        self.parse_messages()
        self.parse_services()

    def add_struct(self, sd: StructDef):
        if sd.name in self.structs:
            # Merge XMLName if missing, otherwise keep first definition like observed duplicate-prone generator.
            old = self.structs[sd.name]
            if not old.fields and sd.fields: old.fields = sd.fields
            if not old.xml_name and sd.xml_name: old.xml_name = sd.xml_name; old.xml_ns = sd.xml_ns
            if not old.alias and sd.alias: old.alias = sd.alias
            if sd.enum_values and not old.enum_values: old.enum_values = sd.enum_values
            return old
        self.structs[sd.name] = sd
        self.order.append(sd.name)
        return sd

    def emit_builtin_aliases(self):
        self.add_struct(StructDef('AnyType', fields=[FieldDef('InnerXML','InnerXML','string')]))
        self.add_struct(StructDef('AnyURI', alias='string'))
        self.add_struct(StructDef('NCName', alias='string'))

    def is_builtin(self, typ):
        return typ in {'string','normalizedString','token','language','Name','NCName','anyURI','ID','IDREF','boolean','bool','int','integer','positiveInteger','nonPositiveInteger','negativeInteger','nonNegativeInteger','long','short','byte','unsignedInt','unsignedLong','unsignedShort','unsignedByte','float','double','decimal','dateTime','date','time','base64Binary','hexBinary','anyType'}

    def go_type_for_qname(self, q, nillable=False, repeated=False):
        typ = strip_prefix(q)
        pfx = prefix(q)
        builtin = self.go_builtin_type(typ)
        if builtin:
            got = builtin
        else:
            got = go_name(typ)
            # simpleType aliases are value-ish; complex types are pointer-ish when single.
            if not repeated:
                got = '*' + got
        if typ in self.structs and self.structs[typ].alias and not repeated:
            # enum/simple alias fields are pointers in observed output for named non-builtin simple types.
            got = '*' + go_name(typ)
        if repeated:
            base = got
            if base.startswith('*'):
                got = '[]' + base
            else:
                # Original uses [] for primitives and []* for complex named types.
                got = '[]' + base
        elif nillable and builtin in ('soap.XSDDateTime','soap.XSDDate'):
            got = '*' + builtin
        return got

    def go_builtin_type(self, typ):
        m = {
            'string':'string','normalizedString':'string','token':'string','language':'string','Name':'string','NCName':'NCName','ID':'string','IDREF':'string','anyURI':'AnyURI',
            'boolean':'bool','bool':'bool','int':'int32','integer':'int32','positiveInteger':'int32','nonPositiveInteger':'int32','negativeInteger':'int32','nonNegativeInteger':'int32',
            'long':'int64','short':'int32','byte':'int32','unsignedInt':'uint32','unsignedLong':'uint64','unsignedShort':'uint16','unsignedByte':'uint8',
            'float':'float32','double':'float64','decimal':'float64','dateTime':'soap.XSDDateTime','date':'soap.XSDDate','time':'soap.XSDTime',
            'base64Binary':'[]byte','hexBinary':'[]byte','anyType':'AnyType'
        }
        return m.get(typ)

    def parse_simple_type(self, name, elem):
        restriction = first(elem, 'restriction')
        if restriction is None:
            # union/list are represented as string.
            sd = StructDef(go_name(name), alias='string')
            self.add_struct(sd); return sd
        base = strip_prefix(restriction.attrib.get('base','string'))
        got = self.go_builtin_type(base) or go_name(base)
        sd = StructDef(go_name(name), alias=got)
        enums = []
        for en in children(restriction, 'enumeration'):
            enums.append((en.attrib.get('value',''), doc_text(en)))
        sd.enum_values = enums
        if got in ('soap.XSDDateTime','soap.XSDDate','soap.XSDTime'):
            sd.date_alias = True
        self.add_struct(sd)
        return sd

    def parse_global_element(self, elem, tns):
        name = elem.attrib.get('name')
        if not name: return None
        gname = go_name(name)
        ct = first(elem, 'complexType')
        st = first(elem, 'simpleType')
        typ = elem.attrib.get('type')
        if ct is not None:
            sd = self.parse_complex_type(gname, ct, tns, is_global_type=False)
            sd.xml_name = name; sd.xml_ns = tns
            return sd
        if st is not None:
            sd = self.parse_simple_type(gname, st)
            return sd
        if typ:
            typ_local = strip_prefix(typ)
            builtin = self.go_builtin_type(typ_local)
            if builtin:
                sd = StructDef(gname, alias=builtin)
                if builtin in ('soap.XSDDateTime','soap.XSDDate','soap.XSDTime'):
                    sd.date_alias = True
                self.add_struct(sd)
                return sd
            # If top-level element maps directly to a named complex type with a different name, original often emits alias.
            if gname != go_name(typ_local):
                sd = StructDef(gname, alias=go_name(typ_local))
                self.add_struct(sd)
        return None

    def find_content_particles(self, elem):
        # sequence/all/choice may appear directly or inside extension/restriction.
        for nm in ('sequence','all','choice'):
            c = first(elem, nm)
            if c is not None: return c
        return None

    def parse_complex_type(self, name, elem, tns, is_global_type=False):
        gname = go_name(name)
        sd = StructDef(gname)
        if is_global_type:
            if gname in self.type_to_element:
                sd.xml_name = self.type_to_element[gname]
                sd.xml_ns = self.type_to_element_ns.get(gname, tns)
        complexContent = first(elem, 'complexContent')
        simpleContent = first(elem, 'simpleContent')
        content_root = elem
        if complexContent is not None:
            ext = first(complexContent, 'extension') or first(complexContent, 'restriction')
            if ext is not None:
                base = strip_prefix(ext.attrib.get('base',''))
                if base:
                    sd.fields.append(FieldDef('', go_name(base), '*' + go_name(base), embed=True))
                content_root = ext
        elif simpleContent is not None:
            ext = first(simpleContent, 'extension') or first(simpleContent, 'restriction')
            if ext is not None:
                base = strip_prefix(ext.attrib.get('base','string'))
                sd.fields.append(FieldDef('', 'Value', self.go_builtin_type(base) or go_name(base), chardata=True))
                content_root = ext
        part = self.find_content_particles(content_root)
        if part is not None:
            for e in children(part):
                if local(e.tag) == 'element':
                    fd = self.field_from_element(e, tns)
                    if fd: sd.fields.append(fd)
                elif local(e.tag) in ('sequence','choice','all'):
                    for ee in children(e, 'element'):
                        fd = self.field_from_element(ee, tns)
                        if fd: sd.fields.append(fd)
        # attributes direct on elem/content extension
        for a in children(content_root, 'attribute') + children(elem, 'attribute'):
            fd = self.field_from_attribute(a, tns)
            if fd: sd.fields.append(fd)
        self.add_struct(sd)
        return self.structs[gname]

    def field_from_element(self, e, tns):
        name = e.attrib.get('name') or strip_prefix(e.attrib.get('ref',''))
        if not name: return None
        doc = doc_text(e)
        maxo = e.attrib.get('maxOccurs','1')
        repeated = (maxo == 'unbounded') or (maxo.isdigit() and int(maxo)>1)
        nillable = e.attrib.get('nillable','false') == 'true'
        st = first(e, 'simpleType')
        ct = first(e, 'complexType')
        if st is not None:
            # For local simple types with enum/date on global elements, a named alias may already exist; fields use primitive.
            res = first(st, 'restriction')
            base = strip_prefix(res.attrib.get('base','string')) if res is not None else 'string'
            typ = self.go_builtin_type(base) or go_name(base)
        elif ct is not None:
            anon = self.parse_anonymous_struct(ct, tns)
            typ = ('[]' if repeated else '') + 'struct'
            return FieldDef(name, go_name(name), typ, doc=doc, anonymous=anon)
        else:
            typ_ref = e.attrib.get('type') or e.attrib.get('ref')
            typ = self.go_type_for_qname(typ_ref or 'string', nillable=nillable, repeated=repeated)
        return FieldDef(name, go_name(name), typ, doc=doc)

    def parse_anonymous_struct(self, ct, tns):
        sd = StructDef('')
        simpleContent = first(ct, 'simpleContent')
        content_root = ct
        if simpleContent is not None:
            ext = first(simpleContent, 'extension') or first(simpleContent, 'restriction')
            if ext is not None:
                base = strip_prefix(ext.attrib.get('base','string'))
                sd.fields.append(FieldDef('', 'Value', self.go_builtin_type(base) or go_name(base), chardata=True))
                content_root = ext
        complexContent = first(ct, 'complexContent')
        if complexContent is not None:
            ext = first(complexContent, 'extension') or first(complexContent, 'restriction')
            if ext is not None:
                base = strip_prefix(ext.attrib.get('base',''))
                if base: sd.fields.append(FieldDef('', go_name(base), '*' + go_name(base), embed=True))
                content_root = ext
        part = self.find_content_particles(content_root)
        if part is not None:
            for e in children(part, 'element'):
                fd = self.field_from_element(e, tns)
                if fd: sd.fields.append(fd)
        for a in children(content_root, 'attribute') + children(ct, 'attribute'):
            fd = self.field_from_attribute(a, tns)
            if fd: sd.fields.append(fd)
        return sd

    def field_from_attribute(self, a, tns):
        name = a.attrib.get('name')
        if not name and a.attrib.get('ref'):
            name = strip_prefix(a.attrib.get('ref'))
            if name in self.global_attrs:
                ga = self.global_attrs[name]
                # use global attr's content/type if local lacks it
                typ_ref = a.attrib.get('type') or ga.attrib.get('type')
                st = first(ga, 'simpleType')
            else:
                typ_ref = a.attrib.get('type')
                st = None
        else:
            typ_ref = a.attrib.get('type')
            st = first(a, 'simpleType')
        if not name: return None
        doc = doc_text(a)
        if st is not None:
            res = first(st, 'restriction')
            base = strip_prefix(res.attrib.get('base','string')) if res is not None else 'string'
            typ = self.go_builtin_type(base) or go_name(base)
        elif typ_ref:
            typ = self.go_type_for_qname(typ_ref)
            if typ.startswith('*') and strip_prefix(typ_ref) in self.structs and self.structs[strip_prefix(typ_ref)].alias:
                pass
        else:
            typ = 'string'
        # Attribute named type should not be pointer for builtin aliases? observed WorkerReferenceEnumeration pointer; keep pointers for nonbuiltin.
        return FieldDef(name, go_name(name), typ, is_attr=True, ns=tns, doc=doc)

    def parse_messages(self):
        for m in children(self.root, 'message'):
            name = m.attrib.get('name')
            if not name: continue
            parts=[]
            ps=children(m,'part')
            if not ps:
                print(f"🍀  [WARN] {name} message doesn't have any parts, ignoring message...")
            for p in ps:
                parts.append(MessagePart(p.attrib.get('name',''), strip_prefix(p.attrib.get('element','')), strip_prefix(p.attrib.get('type',''))))
            self.messages[name]=parts

    def part_go_type(self, part: MessagePart):
        if part.element:
            el = part.element
            return go_name(el)
        if part.type:
            builtin = self.go_builtin_type(part.type)
            if builtin:
                # For message types, built-in string input becomes EmptyString in observed HTTP bindings; other builtins use aliases when available.
                if part.type == 'string': return 'EmptyString'
                return builtin if builtin.startswith('soap.') else go_name(part.type)
            return go_name(part.type)
        return 'EmptyString'

    def parse_services(self):
        for pt in children(self.root, 'portType'):
            ptname = strip_prefix(pt.attrib.get('name',''))
            ops=[]
            for op in children(pt,'operation'):
                oname=op.attrib.get('name','')
                doc=doc_text(op)
                inp=first(op,'input'); out=first(op,'output')
                im=strip_prefix(inp.attrib.get('message','')) if inp is not None else ''
                om=strip_prefix(out.attrib.get('message','')) if out is not None else ''
                ops.append(Operation(oname, im, om, doc))
            self.port_types[ptname]=ops
        # bindings provide actions and choose interface names (binding name in many WSDLs; portType when same)
        bound_pt_names=set()
        for b in children(self.root,'binding'):
            bname=b.attrib.get('name','')
            ptname=strip_prefix(b.attrib.get('type',''))
            actions={}
            for op in children(b,'operation'):
                on=op.attrib.get('name','')
                act="''"
                for c in list(op):
                    if local(c.tag)=='operation' and 'soapAction' in c.attrib:
                        act=c.attrib.get('soapAction') or "''"
                        break
                actions[on]=act
            self.bindings[bname]=(ptname,actions)
            if ptname in self.port_types:
                bound_pt_names.add(ptname)
                iface_name=go_name(ptname)
                # If binding is a SOAP 1.2 sibling (Soap12), original still emits same portType once? It emits duplicate? Ferry has only port type names for all three.
                if iface_name in [i.name for i in self.interfaces]:
                    continue
                ops=[]
                for op in self.port_types[ptname]:
                    nop=Operation(op.name, op.input_msg, op.output_msg, op.doc, actions.get(op.name,"''"))
                    self.resolve_op_types(nop)
                    ops.append(nop)
                self.interfaces.append(ServiceInterface(iface_name, ops))
        for ptname, ops0 in self.port_types.items():
            if ptname not in bound_pt_names:
                ops=[]
                for op in ops0:
                    nop=Operation(op.name, op.input_msg, op.output_msg, op.doc, "''")
                    self.resolve_op_types(nop); ops.append(nop)
                self.interfaces.append(ServiceInterface(go_name(ptname), ops))

    def resolve_op_types(self, op: Operation):
        parts=self.messages.get(op.input_msg,[])
        op.req_type=self.part_go_type(parts[0]) if parts else 'EmptyString'
        parts=self.messages.get(op.output_msg,[])
        op.resp_type=self.part_go_type(parts[0]) if parts else 'EmptyString'

    def render(self):
        out=[]
        w=out.append
        w('// Code generated by gowsdl DO NOT EDIT.')
        w('')
        w(f'package {self.package}')
        w('')
        w('import (')
        w('\t"context"')
        w('\t"encoding/xml"')
        w('\t"github.com/hooklift/gowsdl/soap"')
        w('\t"time"')
        w(')')
        w('')
        w('// against "unused imports"')
        w('var _ time.Time')
        w('var _ xml.Name')
        w('')
        for name in self.order:
            sd=self.structs[name]
            self.render_struct(sd,out)
        for iface in self.interfaces:
            self.render_interface(iface,out)
        return '\n'.join(out).rstrip()+"\n"

    def render_doc(self, out, doc, indent=''):
        if not doc: return
        # Original emits bare comment text, wrapping sometimes by gofmt. Keep simple.
        for line in doc.split('\n'):
            out.append(f'{indent}// {line}')

    def render_struct(self, sd, out):
        w=out.append
        if sd.name == 'AnyType':
            w('type AnyType struct {')
            w('\tInnerXML string `xml:",innerxml"`')
            w('}')
            w('')
            return
        if sd.alias:
            w(f'type {sd.name} {sd.alias}')
            w('')
            if sd.enum_values:
                w('const (')
                for val,doc in sd.enum_values:
                    if doc:
                        w('')
                        self.render_doc(out, doc, '\t')
                    cname = sd.name + sanitize_const_suffix(val)
                    w(f'\t{cname} {sd.name} = "{val}"')
                    w('')
                if out[-1]=='': out.pop()
                w(')')
                w('')
            if sd.date_alias:
                base=sd.alias
                w(f'func (xdt {sd.name}) MarshalXML(e *xml.Encoder, start xml.StartElement) error {{')
                w(f'\treturn {base}(xdt).MarshalXML(e, start)')
                w('}')
                w('')
                w(f'func (xdt *{sd.name}) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {{')
                w(f'\treturn (*{base})(xdt).UnmarshalXML(d, start)')
                w('}')
                w('')
            return
        w(f'type {sd.name} struct {{')
        if sd.xml_name:
            w(f'\tXMLName xml.Name `xml:"{sd.xml_ns} {sd.xml_name}"`')
            if sd.fields: w('')
        for idx,f in enumerate(sd.fields):
            self.render_field(f,out,'\t')
            if idx != len(sd.fields)-1: w('')
        w('}')
        w('')

    def render_field(self, f, out, indent):
        w=out.append
        if f.doc:
            self.render_doc(out,f.doc,indent)
        if f.embed:
            w(f'{indent}{f.go_type}')
            return
        if f.chardata:
            w(f'{indent}{f.go_name} {f.go_type} `xml:",chardata" json:"-,"`')
            return
        if f.anonymous:
            prefix = '[]struct {' if f.go_type.startswith('[]') else 'struct {'
            w(f'{indent}{f.go_name} {prefix}')
            if f.anonymous.fields:
                w('')
            for i,af in enumerate(f.anonymous.fields):
                self.render_field(af,out,indent+'\t')
                if i != len(f.anonymous.fields)-1: w('')
            tag=f'`xml:"{f.xml_name},omitempty" json:"{f.xml_name},omitempty"`'
            w(f'{indent}}} {tag}')
            return
        if f.is_attr:
            tag=f'`xml:"{f.ns} {f.xml_name},attr,omitempty" json:"{f.xml_name},omitempty"`'
        else:
            tag=f'`xml:"{f.xml_name},omitempty" json:"{f.xml_name},omitempty"`'
        w(f'{indent}{f.go_name} {f.go_type} {tag}')

    def render_interface(self, iface, out):
        w=out.append
        w(f'type {iface.name} interface {{')
        for op in iface.operations:
            if op.doc:
                w('')
                w(f'\t/* {op.doc} */')
            w(f'\t{go_name(op.name)}(request *{op.req_type}) (*{op.resp_type}, error)')
            w('')
            w(f'\t{go_name(op.name)}Context(ctx context.Context, request *{op.req_type}) (*{op.resp_type}, error)')
            w('')
        if iface.operations and out[-1]=='': out.pop()
        w('}')
        w('')
        priv=private_name(iface.name)
        w(f'type {priv} struct {{')
        w('\tclient *soap.Client')
        w('}')
        w('')
        w(f'func New{iface.name}(client *soap.Client) {iface.name} {{')
        w(f'\treturn &{priv}{{')
        w('\t\tclient: client,')
        w('\t}')
        w('}')
        w('')
        for op in iface.operations:
            mn=go_name(op.name)
            action=op.action if op.action is not None and op.action!='' else "''"
            w(f'func (service *{priv}) {mn}Context(ctx context.Context, request *{op.req_type}) (*{op.resp_type}, error) {{')
            w(f'\tresponse := new({op.resp_type})')
            w(f'\terr := service.client.CallContext(ctx, "{action}", request, response)')
            w('\tif err != nil {')
            w('\t\treturn nil, err')
            w('\t}')
            w('')
            w('\treturn response, nil')
            w('}')
            w('')
            w(f'func (service *{priv}) {mn}(request *{op.req_type}) (*{op.resp_type}, error) {{')
            w(f'\treturn service.{mn}Context(')
            w('\t\tcontext.Background(),')
            w('\t\trequest,')
            w('\t)')
            w('}')
            w('')

    def render_server(self):
        out=[]; w=out.append
        w('// Code generated by gowsdl DO NOT EDIT.')
        w('')
        w(f'package {self.package}')
        w('')
        w('import (')
        w('\t"encoding/xml"')
        w('\t"errors"')
        w('\t"fmt"')
        w('\t"net/http"')
        w('\t"reflect"')
        w('\t"strings"')
        w(')')
        w('')
        escaped = self.wsdl_text.replace('`','` + "`" + `')
        w('var wsdl = `'+escaped+'`')
        w('')
        w('var WSDLUndefinedError = errors.New("Server was unable to process request. --> Object reference not set to an instance of an object.")')
        w('')
        w('type SOAPEnvelopeRequest struct {')
        w('\tXMLName xml.Name `xml:"http://schemas.xmlsoap.org/soap/envelope/ Envelope"`')
        w('\tBody    SOAPBodyRequest')
        w('}')
        w('')
        reqs=[]
