USAGE_TMPL = "Usage: {prog} [options] myservice.wsdl\n  -d string\n    \tDirectory under which package directory will be created (default \"./\")\n  -i\tSkips TLS Verification\n  -make-public\n    \tMake the generated types public/exported (default true)\n  -o string\n    \tFile where the generated code will be saved (default \"myservice.go\")\n  -p string\n    \tPackage under which code will be generated (default \"myservice\")\n  -v\tShows gowsdl version\n"

def usage(prog):
    return USAGE_TMPL.format(prog=prog)

def parse_args(argv):
    prog=argv[0]
    opts={'d':'./','o':'myservice.go','p':'myservice','i':False,'make_public':True,'v':False}
    args=[]; i=1
    while i < len(argv):
        a=argv[i]
        if a in ('-h','--help'):
            sys.stderr.write(usage(prog)); sys.exit(0)
        if a == '-v':
            opts['v']=True; i+=1; continue
        if a == '-i':
            opts['i']=True; i+=1; continue
        if a.startswith('-make-public'):
            val=None
            if a == '-make-public':
                # optional bool value only if next token is true/false
                if i+1 < len(argv) and argv[i+1].lower() in ('true','false'):
                    val=argv[i+1]; i+=1
                else:
                    val='true'
            elif a.startswith('-make-public='):
                val=a.split('=',1)[1]
            else:
                sys.stderr.write(f'flag provided but not defined: {a}\n')
                sys.stderr.write(usage(prog)); sys.exit(2)
            opts['make_public']=(val.lower()!='false')
            i+=1; continue
        if a in ('-d','-o','-p') or a.startswith('-d=') or a.startswith('-o=') or a.startswith('-p='):
            key=a[1]
            if '=' in a:
                val=a.split('=',1)[1]
            else:
                if i+1 >= len(argv):
                    sys.stderr.write(f'flag needs an argument: {a}\n')
                    sys.stderr.write(usage(prog)); sys.exit(2)
                val=argv[i+1]; i+=1
            opts[key]=val; i+=1; continue
        if a.startswith('-'):
            sys.stderr.write(f'flag provided but not defined: {a}\n')
            sys.stderr.write(usage(prog)); sys.exit(2)
        args.append(a); i+=1
    return prog, opts, args

def main(argv):
    prog,opts,args=parse_args(argv)
    if opts['v']:
        print('🍀  v0.5.0')
        return 0
    if not args:
        sys.stderr.write(usage(prog))
        return 0
    wsdl=args[-1] if len(args)>1 else args[0]
    try:
        gen=Generator(wsdl, opts['p'], opts['make_public'], opts['i'])
        gen.load(); gen.build()
        outdir=os.path.join(opts['d'], opts['p'])
        os.makedirs(outdir, exist_ok=True)
        outpath=os.path.join(outdir, opts['o'])
        # do not create nested dirs beneath package: open failure matches original
        with open(outpath,'w',encoding='utf-8') as f: f.write(gen.render())
        base=os.path.basename(opts['o'])
        server='server'+base
        with open(os.path.join(outdir, server),'w',encoding='utf-8') as f: f.write(gen.render_server())
        print('🍀  Done 👍')
        return 0
    except FileNotFoundError as e:
        print(f'🍀  {e}')
        return 1
    except Exception as e:
        print(f'🍀  {e}')
        return 1

if __name__=='__main__':
    sys.exit(main(sys.argv))
